cat > waves.js <<'EOF'
// Shared wave maths. The hero wave is stationary in the scene (the camera and
// the surfer ride along with it); the sea streams through it toward -z.
// Everything here is mirrored in GLSL so the CPU (board, pelican, wake) and the
// GPU (ocean mesh) agree on where the water is.
import * as THREE from "three";

export const SLOPE = 0.12; // crest line tilt: crest z = SLOPE * x
export const A0 = 4.1; // hero wave height
export const BACK = 9.0; // gentle back-of-wave width
export const FRONT = 3.3; // steep face width
export const CURL = 2.0; // forward throw of the lip
export const CURL_C = 1.0; // lip centre (distance past the crest)
export const CURL_W = 1.25;

// kx, kz, speed, amplitude: ambient swell + chop
export const AMBIENT = [
  [0.038, 0.257, 0.9, 0.35],
  [-0.21, 0.51, 1.3, 0.16],
  [1.2, 1.2, 2.6, 0.05],
  [-2.0, 1.6, 3.1, 0.03],
  [0.7, 3.0, 4.0, 0.015],
];

const f = (n) => (Number.isInteger(n) ? n.toFixed(1) : String(n));

export const waveGLSL = /* glsl */ `
const float SLOPE = ${f(SLOPE)};
const float A0 = ${f(A0)};
float heroAmp(float x) {
  return A0 * (0.5 + 0.5 * exp(-pow(x / 40.0, 2.0))) * (1.0 + 0.05 * sin(uTime * 0.45));
}
float ambientH(vec2 p) {
  float h = 0.0;
  ${AMBIENT.map(([kx, kz, w, a]) => `h += ${f(a)} * sin(${f(kx)} * p.x + ${f(kz)} * p.y + ${f(w)} * uTime);`).join("\n  ")}
  return h;
}
// p = rest position (x0, z0) of a water particle; returns its world position.
// outputs: u = distance past the crest line, prof = hero profile 0..1
vec3 surf(vec2 p, out float u, out float prof) {
  u = p.y - SLOPE * p.x;
  float amp = heroAmp(p.x);
  prof = u < 0.0 ? exp(-pow(u / ${f(BACK)}, 2.0)) : exp(-pow(u / ${f(FRONT)}, 2.0));
  float curl = ${f(CURL)} * exp(-pow(p.x / 22.0, 2.0)) * exp(-pow((u - ${f(CURL_C)}) / ${f(CURL_W)}, 2.0));
  return vec3(p.x, amp * prof + ambientH(p), p.y + curl);
}
`;

export function heroAmp(x, t) {
  return A0 * (0.5 + 0.5 * Math.exp(-((x / 40) ** 2))) * (1 + 0.05 * Math.sin(t * 0.45));
}

export function ambientH(x, z, t) {
  let h = 0;
  for (const [kx, kz, w, a] of AMBIENT) h += a * Math.sin(kx * x + kz * z + w * t);
  return h;
}

export function surface(x0, z0, t, out = new THREE.Vector3()) {
  const u = z0 - SLOPE * x0;
  const amp = heroAmp(x0, t);
  const prof = u < 0 ? Math.exp(-((u / BACK) ** 2)) : Math.exp(-((u / FRONT) ** 2));
  const curl = CURL * Math.exp(-((x0 / 22) ** 2)) * Math.exp(-(((u - CURL_C) / CURL_W) ** 2));
  return out.set(x0, amp * prof + ambientH(x0, z0, t), z0 + curl);
}

const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
const _c = new THREE.Vector3();
const _d = new THREE.Vector3();
// smoothed surface normal around a rest position
export function surfaceNormal(x0, z0, t, e = 0.7, out = new THREE.Vector3()) {
  const px = _a.copy(surface(x0 + e, z0, t, _c)).sub(surface(x0 - e, z0, t, _d));
  const pz = _b.copy(surface(x0, z0 + e, t, _c)).sub(surface(x0, z0 - e, t, _d));
  return out.crossVectors(pz, px).normalize();
}
EOF

cat > sky.js <<'EOF'
import * as THREE from "three";

export const SUN_DIR = new THREE.Vector3(-0.6, 0.25, -0.75).normalize();

export const noiseGLSL = /* glsl */ `
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
  float s = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    s += a * vnoise(p);
    p = p * 2.03 + vec2(17.3, 9.1);
    a *= 0.5;
  }
  return s;
}
`;

// Golden-hour sky. Expects uniforms: uTime, uSunDir.
export const skyGLSL = /* glsl */ `
${noiseGLSL}
vec3 skyColor(vec3 d, bool withSun) {
  float h = max(d.y, 0.0);
  vec3 zen = vec3(0.07, 0.20, 0.50);
  vec3 mid = vec3(0.30, 0.52, 0.78);
  vec3 hor = vec3(1.00, 0.70, 0.46);
  vec3 col = mix(hor, mid, pow(smoothstep(0.0, 0.32, h), 0.55));
  col = mix(col, zen, smoothstep(0.22, 0.95, h));
  float s = max(dot(d, uSunDir), 0.0);
  col += vec3(1.0, 0.45, 0.18) * pow(s, 5.0) * 0.55;
  col += vec3(1.0, 0.72, 0.42) * pow(s, 36.0) * 0.9;
  if (withSun) col += vec3(14.0, 10.0, 6.5) * smoothstep(0.99935, 0.99965, s);

  // layered clouds on a flat plane
  if (d.y > 0.0) {
    vec2 p = d.xz / (d.y + 0.12) * 0.9 + vec2(uTime * 0.012, uTime * 0.004);
    float n = fbm(p * 0.9);
    float n2 = fbm(p * 0.9 + uSunDir.xz * 0.12);
    float cover = smoothstep(0.50, 0.78, n);
    float lit = clamp(0.5 + (n - n2) * 5.0, 0.0, 1.0);
    vec3 shade = mix(vec3(0.42, 0.40, 0.55), vec3(0.75, 0.52, 0.45), pow(1.0 - h, 2.0));
    vec3 bright = mix(vec3(1.0, 0.82, 0.62), vec3(1.0, 0.93, 0.85), h);
    vec3 cc = mix(shade, bright, lit);
    cc += vec3(1.0, 0.6, 0.3) * pow(s, 8.0) * 0.8 * (1.0 - cover * 0.3);
    float fade = smoothstep(0.02, 0.16, d.y);
    col = mix(col, cc, cover * fade * 0.92);
  }
  return col;
}
`;

const vertex = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const fragment = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
varying vec3 vDir;
${skyGLSL}
void main() {
  gl_FragColor = vec4(skyColor(normalize(vDir), true), 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createSky() {
  const uniforms = {
    uTime: { value: 0 },
    uSunDir: { value: SUN_DIR },
  };
  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: vertex,
    fragmentShader: fragment,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  });
  const dome = new THREE.Mesh(new THREE.SphereGeometry(3000, 48, 24), material);
  dome.frustumCulled = false;
  dome.renderOrder = -10;
  return { dome, uniforms, material };
}

// Bake the sky into an environment map for the PBR materials.
export function bakeEnvironment(renderer, skyMaterial) {
  const envScene = new THREE.Scene();
  const m = new THREE.Mesh(new THREE.SphereGeometry(50, 32, 16), skyMaterial);
  envScene.add(m);
  const pmrem = new THREE.PMREMGenerator(renderer);
  const rt = pmrem.fromScene(envScene, 0.02);
  pmrem.dispose();
  return rt.texture;
}
EOF

cat > ocean.js <<'EOF'
import * as THREE from "three";
import { waveGLSL } from "./waves.js";
import { skyGLSL, SUN_DIR } from "./sky.js";

// 1D vertex coordinates: fine spacing in the core, growing outward.
function axis(lo, hi, coreLo, coreHi, step, grow) {
  const out = [];
  for (let v = coreLo; v <= coreHi + 1e-6; v += step) out.push(v);
  let s = step;
  for (let v = coreHi; v < hi; ) {
    s *= grow;
    v += s;
    out.push(v);
  }
  s = step;
  for (let v = coreLo; v > lo; ) {
    s *= grow;
    v -= s;
    out.unshift(v);
  }
  return out;
}

function buildGrid() {
  const xs = axis(-900, 900, -28, 28, 0.28, 1.06);
  const zs = axis(-1000, 80, -10, 14, 0.14, 1.06);
  const nx = xs.length;
  const nz = zs.length;
  const pos = new Float32Array(nx * nz * 3);
  for (let j = 0; j < nz; j++) {
    for (let i = 0; i < nx; i++) {
      const k = (j * nx + i) * 3;
      pos[k] = xs[i];
      pos[k + 2] = zs[j];
    }
  }
  const idx = new Uint32Array((nx - 1) * (nz - 1) * 6);
  let q = 0;
  for (let j = 0; j < nz - 1; j++) {
    for (let i = 0; i < nx - 1; i++) {
      const a = j * nx + i;
      const b = a + 1;
      const c = a + nx;
      const d = c + 1;
      idx[q++] = a;
      idx[q++] = c;
      idx[q++] = b;
      idx[q++] = b;
      idx[q++] = c;
      idx[q++] = d;
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setIndex(new THREE.BufferAttribute(idx, 1));
  return g;
}

const vertex = /* glsl */ `
uniform float uTime;
varying vec3 vWorld;
varying vec3 vNormal;
varying vec2 vRest;
varying float vU;
varying float vProf;
varying float vAmp;

${waveGLSL}

void main() {
  vec2 p = position.xz;
  float u, prof;
  vec3 P = surf(p, u, prof);
  float e = 0.1;
  float u2, p2;
  vec3 px = surf(p + vec2(e, 0.0), u2, p2) - surf(p - vec2(e, 0.0), u2, p2);
  vec3 pz = surf(p + vec2(0.0, e), u2, p2) - surf(p - vec2(0.0, e), u2, p2);
  vNormal = normalize(cross(pz, px));
  vWorld = P;
  vRest = p;
  vU = u;
  vProf = prof;
  vAmp = heroAmp(p.x);
  gl_Position = projectionMatrix * viewMatrix * vec4(P, 1.0);
}
`;

const fragment = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
varying vec3 vWorld;
varying vec3 vNormal;
varying vec2 vRest;
varying float vU;
varying float vProf;
varying float vAmp;

${skyGLSL}

void main() {
  vec3 L = uSunDir;
  vec3 V = normalize(cameraPosition - vWorld);
  vec3 N = normalize(vNormal);
  if (dot(N, V) < 0.0) N = -N;
  float dist = length(cameraPosition - vWorld);

  // fine ripples, scrolling toward the wave
  vec2 rp = vec2(vWorld.x * 1.6, vWorld.z * 1.6 + uTime * 1.8);
  float r0 = vnoise(rp);
  float rx = vnoise(rp + vec2(0.07, 0.0));
  float rz = vnoise(rp + vec2(0.0, 0.07));
  vec2 rp2 = vec2(vWorld.x * 4.1 - uTime * 0.4, vWorld.z * 4.1 + uTime * 2.6);
  float s0 = vnoise(rp2);
  float sx = vnoise(rp2 + vec2(0.07, 0.0));
  float sz = vnoise(rp2 + vec2(0.0, 0.07));
  float rippleFade = exp(-dist * 0.012);
  N = normalize(N + vec3(rx - r0, 0.0, rz - r0) * 0.55 * rippleFade
                  + vec3(sx - s0, 0.0, sz - s0) * 0.28 * rippleFade);

  float ndv = max(dot(N, V), 0.0);
  float fres = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);

  // body colour: dark troughs, glowing turquoise on the lit face
  float hn = clamp(vWorld.y / 4.0, 0.0, 1.0);
  vec3 deep = vec3(0.010, 0.075, 0.120);
  vec3 mid = vec3(0.020, 0.250, 0.300);
  vec3 glow = vec3(0.10, 0.62, 0.48);
  vec3 body = mix(deep, mid, smoothstep(0.0, 0.45, hn));
  float diff = max(dot(N, L), 0.0);
  body *= 0.55 + 0.9 * diff;

  // light shining through the thin, steep part of the wave (sun behind it)
  float toSun = max(dot(-V, L), 0.0);
  float thin = smoothstep(0.30, 0.95, vProf) * smoothstep(-0.2, 0.7, N.z);
  float back = 0.30 + 1.5 * pow(toSun, 1.5);
  body += glow * thin * back * (0.35 + 0.65 * smoothstep(0.3, 1.0, hn));
  body += vec3(0.8, 0.9, 0.3) * pow(thin, 4.0) * pow(toSun, 3.0) * 0.5;

  vec3 R = reflect(-V, N);
  R.y = abs(R.y);
  vec3 refl = skyColor(normalize(R), false);
  vec3 col = mix(body, refl, fres);

  // sun glitter
  vec3 H = normalize(L + V);
  float nh = max(dot(N, H), 0.0);
  float spec = pow(nh, 420.0) * 9.0 + pow(nh, 60.0) * 0.45;
  col += vec3(1.0, 0.78, 0.5) * spec;

  // --- foam ---
  float u = vU;
  float x = vRest.x;
  // lip & crest
  float lipN = fbm(vec2(x * 1.3, u * 1.6 - uTime * 0.3));
  float lip = smoothstep(0.70, 0.96, vProf) * smoothstep(-0.2, 0.4, u);
  lip *= smoothstep(0.25, 0.55, lipN + 0.35);
  // streaks tumbling down the face
  float streakN = fbm(vec2(x * 2.4, u * 0.55 - uTime * 1.1));
  float streak = smoothstep(0.52, 0.72, streakN) * smoothstep(3.6, 1.6, u) * smoothstep(0.0, 0.8, u);
  streak *= exp(-pow(x / 24.0, 2.0)) * 0.85 + 0.15;
  // churned foot of the wave
  float footN = fbm(vec2(x * 0.9, (u + uTime * 0.7) * 0.8));
  float foot = smoothstep(0.50, 0.75, footN) * smoothstep(3.2, 5.0, u) * smoothstep(11.0, 6.0, u) * 0.75;
  // white water where the wave has already closed out
  float closed = smoothstep(14.0, 26.0, abs(x));
  float whiteN = fbm(vec2(x * 0.7, (u + uTime * 0.9) * 0.7) + 3.0);
  float white = closed * smoothstep(0.38, 0.6, whiteN) * smoothstep(-3.0, 0.5, u) * smoothstep(16.0, 8.0, u);
  // flecks drifting across the open sea
  float fleckN = vnoise(vec2(vWorld.x * 0.9, vWorld.z * 0.9 + uTime * 1.5));
  float fleck = smoothstep(0.82, 0.95, fleckN) * 0.35 * smoothstep(0.4, 1.0, hn + 0.3);

  float foam = clamp(max(max(lip, streak), max(max(foot, white), fleck)), 0.0, 1.0);
  vec3 foamCol = mix(vec3(0.70, 0.84, 0.88), vec3(1.0, 0.97, 0.92), clamp(diff * 0.8 + 0.3, 0.0, 1.0));
  foamCol += vec3(1.0, 0.6, 0.3) * pow(max(dot(N, L), 0.0), 2.0) * 0.15;
  col = mix(col, foamCol, foam * 0.92);

  // aerial perspective
  float fogA = 1.0 - exp(-dist * 0.0050);
  vec3 fogCol = skyColor(normalize(vec3(-V.x, 0.012, -V.z)), false);
  col = mix(col, fogCol, fogA);

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createOcean() {
  const uniforms = {
    uTime: { value: 0 },
    uSunDir: { value: SUN_DIR },
  };
  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: vertex,
    fragmentShader: fragment,
    side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(buildGrid(), material);
  mesh.frustumCulled = false;
  return { mesh, uniforms };
}
EOF

cat > board.js <<'EOF'
import * as THREE from "three";

export const BOARD_LEN = 3.4;
const HALF = BOARD_LEN / 2;

function halfWidth(s) {
  // s: 0 at tail, 1 at nose
  if (s >= 0.45) {
    const k = (s - 0.45) / 0.55;
    return 0.46 * Math.pow(Math.max(1 - k * k, 0), 0.55);
  }
  const k = (0.45 - s) / 0.58;
  return 0.46 * Math.pow(Math.max(1 - k * k, 0), 0.5);
}

const rocker = (z) => 0.16 * Math.pow(Math.abs(z) / HALF, 2.4);

export function createBoard() {
  const shape = new THREE.Shape();
  const N = 48;
  for (let i = 0; i <= N; i++) {
    const s = i / N;
    const y = -(s - 0.5) * BOARD_LEN; // nose at -y -> +z after rotation
    const x = halfWidth(s);
    if (i === 0) shape.moveTo(x, y);
    else shape.lineTo(x, y);
  }
  for (let i = N; i >= 0; i--) {
    const s = i / N;
    shape.lineTo(-halfWidth(s), -(s - 0.5) * BOARD_LEN);
  }
  const depth = 0.07;
  const bevel = 0.05;
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 4,
    curveSegments: 1,
  });
  geo.rotateX(-Math.PI / 2);
  geo.translate(0, -(depth + bevel), 0);
  const p = geo.attributes.position;
  for (let i = 0; i < p.count; i++) p.setY(i, p.getY(i) + rocker(p.getZ(i)));
  geo.computeVertexNormals();

  const deckMat = new THREE.MeshPhysicalMaterial({
    color: 0xff5a36,
    roughness: 0.32,
    clearcoat: 1,
    clearcoatRoughness: 0.15,
  });
  const board = new THREE.Group();
  const body = new THREE.Mesh(geo, deckMat);
  body.castShadow = true;
  body.receiveShadow = true;
  board.add(body);

  // stripes laid just above the deck, following the rocker
  const stripeMat = new THREE.MeshStandardMaterial({
    color: 0xfff4de,
    roughness: 0.4,
    polygonOffset: true,
    polygonOffsetFactor: -2,
    polygonOffsetUnits: -2,
  });
  const addStripe = (xOff, width, color) => {
    const g = new THREE.PlaneGeometry(width, BOARD_LEN * 0.9, 1, 60);
    g.rotateX(-Math.PI / 2);
    const q = g.attributes.position;
    for (let i = 0; i < q.count; i++) {
      const z = q.getZ(i);
      const s = z / BOARD_LEN + 0.5;
      const hw = halfWidth(Math.min(Math.max(s, 0.02), 0.98));
      const x = q.getX(i) + xOff;
      q.setX(i, THREE.MathUtils.clamp(x, -hw * 0.85, hw * 0.85));
      q.setY(i, 0.062 + bevel + rocker(z) - (depth + bevel) + depth * 0 + 0.0);
    }
    g.computeVertexNormals();
    const m = stripeMat.clone();
    m.color.set(color);
    const mesh = new THREE.Mesh(g, m);
    mesh.receiveShadow = true;
    board.add(mesh);
  };
  addStripe(0, 0.13, 0xfff4de);
  addStripe(0.27, 0.05, 0xffd23f);
  addStripe(-0.27, 0.05, 0xffd23f);

  // tail fin peeking out the back, nose-tip dab of colour
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.quadraticCurveTo(0.02, -0.18, 0.2, -0.26);
  finShape.lineTo(0.2, 0);
  const fin = new THREE.Mesh(
    new THREE.ExtrudeGeometry(finShape, { depth: 0.02, bevelEnabled: false }),
    new THREE.MeshStandardMaterial({ color: 0x1b2a3a, roughness: 0.5 })
  );
  fin.rotation.y = -Math.PI / 2;
  fin.position.set(0.01, -0.1, -HALF + 0.45);
  board.add(fin);

  return board;
}
